    public static void confirmReservation(Context ctx) {
        try {
            int id = Integer.parseInt(ctx.pathParam("id"));
            JsonObject body = JsonParser.parseString(ctx.body()).getAsJsonObject();

            if (!body.has("amountPaid")) {
                ctx.status(400).json(new JsonObject() {{
                    addProperty("error", "INVALID_REQUEST");
                    addProperty("message", "amountPaid is required");
                }});
                return;
            }

            BigDecimal amountPaid = body.get("amountPaid").getAsBigDecimal();
            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
            ctx.json(toJson(reservation));
        } catch (NumberFormatException e) {
            ctx.status(400).json(new JsonObject() {{
                addProperty("error", "INVALID_REQUEST");
                addProperty("message", "Invalid reservation ID");
            }});
        } catch (IllegalArgumentException e) {
            String error = e.getMessage();
            int status = "RESERVATION_NOT_FOUND".equals(error) ? 404 : 409;
            ctx.status(status).json(new JsonObject() {{
                addProperty("error", error);
                addProperty("message", error);
            }});
        } catch (Exception e) {
            logger.error("Error confirming reservation", e);
            ctx.status(400).json(new JsonObject() {{
                addProperty("error", "INVALID_REQUEST");
                addProperty("message", "Invalid request");
            }});
        }
