            ctx.status(status).json(new JsonObject() {{
                addProperty("error", error);
                addProperty("message", error);
            }});
        }
    }

    public static void checkOut(Context ctx) {
        try {
            int id = Integer.parseInt(ctx.pathParam("id"));
