    public static void getDocument(Context ctx) {
        try {
            int id = Integer.parseInt(ctx.pathParam("id"));
            Reservation reservation = reservationService.getReservation(id);

            if (!"CONFIRMED".equals(reservation.getStatus()) &&
                !"CHECKED_IN".equals(reservation.getStatus()) &&
                !"CHECKED_OUT".equals(reservation.getStatus())) {
                ctx.status(409).json(new JsonObject() {{
                    addProperty("error", "OPERATION_NOT_ALLOWED");
                    addProperty("message", "Document only available for paid reservations");
                }});
                return;
            }

            Optional<Room> roomOpt = roomDAO.findByNumber(reservation.getRoomNumber());
            if (roomOpt.isEmpty()) {
                ctx.status(500).json(new JsonObject() {{
                    addProperty("error", "INTERNAL_ERROR");
                    addProperty("message", "Room not found");
                }});
                return;
